// Le status de abertura do e-mail (D0), gravado pelo Resend_Webhook_Status
const emailStatus = $('02b_le_email_status').all().map(i => i.json);

const hoje = new Date();
hoje.setHours(0,0,0,0);

const out = [];

for (const item of $input.all()) {
  const lead = item.json;

  if (!lead.data_envio_proposta) continue;

  const dataProposta = new Date(lead.data_envio_proposta);
  dataProposta.setHours(0,0,0,0);

  const diffMs = hoje - dataProposta;
  const dias_corridos = Math.round(diffMs / (1000 * 60 * 60 * 24));

  const dataValidade = new Date(dataProposta);
  dataValidade.setDate(dataValidade.getDate() + 30);

  const statusDoLead = emailStatus.filter(e => e.lead_id === lead.lead_id);
  const d0_aberto = statusDoLead.some(e => e.evento === 'opened');

  out.push({
    json: {
      ...lead,
      dias_corridos,
      d0_aberto,
      data_validade: dataValidade.toISOString().split('T')[0]
    }
  });
}

return out;

